package glitch

import data.glitch_lib

weak_algorithms := {"DES", "3DES", "RC2", "RC4", "BLOWFISH", "MD5", "SHA1", "SHA-1", "PBKDF1", "HMAC-MD5", "HMAC-SHA1", "MD5withRSA", "SHA1withRSA"}

weak_tls_versions := {"SSLv2", "SSLv3", "TLSv1.0", "TLSv1.1", "1.0", "1.1", "TLS-1.0", "TLS-1.1"}

weak_key_sizes := {"64", "56", "40", "1024"}

weak_ssl_policies := {"COMPATIBILITY", "LEGACY", "WEAK", "COMPATIBLE", "ELBSecurityPolicy-TLS-1-0", "ELBSecurityPolicy-TLS-1-1", "TLS-1-0-2010", "TLS-1-1-2017"}

encryption_attr_names := {"algorithm", "cipher", "encryption", "type", "hash_algorithm", "digest", "kdf", "key_derivation", "mac", "hmac", "signature_algorithm", "kms_key_spec", "key_spec", "tls_version", "min_version", "ssl_policy", "tls_policy", "policy", "sse_algorithm"}

key_size_attr_names := {"key_size", "key_length", "key_bits", "rsa_key_size", "modulus_size", "iterations", "iteration_count", "salt_length", "memory", "memory_cost", "parallelism"}

cipher_suite_attr_names := {"cipher_suites", "ciphers"}

storage_encryption_attr_names := {"storage_encrypted", "encryption_at_rest", "rotation"}

contains_weak_algorithm(value) {
    value.ir_type == "String"
    upper := upper(value.value)
    contains(upper, weak_algorithms[_])
}

contains_weak_tls_version(value) {
    value.ir_type == "String"
    contains(upper(value.value), weak_tls_versions[_])
}

contains_weak_key_size(value) {
    value.ir_type == "Integer"
    value.value < 128
} else {
    value.ir_type == "String"
    regex.match("^(64|56|40|1024|2048)$", value.value)
}

contains_weak_ssl_policy(value) {
    value.ir_type == "String"
    contains(upper(value.value), weak_ssl_policies[_])
}

check_string_value(value, patterns) {
    value.ir_type == "String"
    contains(upper(value.value), patterns[_])
}

check_disabled_encryption(value) {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "String"
    upper(value.value) == "FALSE"
}

check_hash_for_weak_cipher(hash, attr_name) {
    hash[attr_name]
    val := hash[attr_name]
    contains_weak_algorithm(val)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name == encryption_attr_names[_]
    contains_weak_algorithm(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Weak or deprecated encryption algorithm detected. (CWE-326)"
    }
}

