weak_key_sizes := {"64", "56", "40", "1024"}

weak_ssl_policies := {"COMPATIBILITY", "LEGACY", "WEAK", "COMPATIBLE", "ELBSecurityPolicy-TLS-1-0", "ELBSecurityPolicy-TLS-1-1", "TLS-1-0-2010", "TLS-1-1-2017"}

encryption_attr_names := {"algorithm", "cipher", "encryption", "encrypt", "type", "hash_algorithm", "digest", "kdf", "key_derivation", "mac", "hmac", "signature_algorithm", "kms_key_spec", "key_spec", "tls_version", "min_version", "ssl_policy", "tls_policy", "policy", "sse_algorithm"}

key_size_attr_names := {"key_size", "key_length", "key_bits", "rsa_key_size", "modulus_size", "iterations", "iteration_count", "salt_length", "memory", "memory_cost", "parallelism"}

cipher_suite_attr_names := {"cipher_suites", "ciphers"}

storage_encryption_attr_names := {"storage_encrypted", "encryption_at_rest", "rotation"}

contains_weak_algorithm(value) {
    value.ir_type == "String"
    u := upper(value.value)
    contains(u, weak_algorithms[_])
}

contains_weak_tls_version(value) {
    value.ir_type == "String"
    contains(upper(value.value), weak_tls_versions[_])
}

contains_weak_key_size(value) {
    value.ir_type == "Integer"
    value.value < 128
} else {
    value.ir_type == "String"
    regex.match("^(64|56|40|1024|2048)$", value.value)
}

contains_weak_ssl_policy(value) {
    value.ir_type == "String"
    contains(upper(value.value), weak_ssl_policies[_])
}

check_disabled_encryption(value) {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "String"
    upper(value.value) == "FALSE"
}

has_weak_algorithm_in_function_call(node) {
    node.ir_type == "FunctionCall"
    arg := node.args[_]
    arg.ir_type == "String"
    upper_arg := upper(arg.value)
    contains(upper_arg, weak_algorithms[_])
}

has_weak_algorithm_in_value(value) {
    contains_weak_algorithm(value)
} else {
    value.ir_type == "FunctionCall"
    has_weak_algorithm_in_function_call(value)
} else {
    walk(value, [_, n])
    n.ir_type == "String"
    upper_n := upper(n.value)
    contains(upper_n, weak_algorithms[_])
}

check_nested_hash_values(hash_value) {
    hash_value.ir_type == "Hash"
    kv := hash_value.value[_]
    key_name := upper(kv.key.value)
    contains(key_name, encryption_attr_names[_])
    contains_weak_algorithm(kv.value)
}

check_array_values(arr_value) {
    arr_value.ir_type == "Array"
    el := arr_value.value[_]
    check_weak_in_nested_value(el)
}

check_weak_in_nested_value(value) {
    contains_weak_algorithm(value)
} else {
    value.ir_type == "Hash"
    check_nested_hash_values(value)
} else {
    value.ir_type == "Array"
    check_array_values(value)
} else {
    walk(value, [_, n])
    n.ir_type == "String"
    upper_n := upper(n.value)
    contains(upper_n, weak_algorithms[_])
}

check_cipher_suites(value) {
    value.ir_type == "String"
    cipher_upper := upper(value.value)
    contains(cipher_upper, "CBC")
    contains(cipher_upper, "SHA")
    not contains(cipher_upper, "SHA256")
    not contains(cipher_upper, "SHA384")
} else {
    value.ir_type == "String"
    cipher_upper := upper(value.value)
    contains(cipher_upper, "NULL")
} else {
    value.ir_type == "String"
    cipher_upper := upper(value.value)
    contains(cipher_upper, "EXPORT")
} else {
    value.ir_type == "String"
    cipher_upper := upper(value.value)
    contains(cipher_upper, "DES")
} else {
    value.ir_type == "String"
    cipher_upper := upper(value.value)
    contains(cipher_upper, "RC4")
}

