weak_algorithms := {"DES", "3DES", "RC2", "RC4", "BLOWFISH", "MD5", "SHA1", "SHA-1", "PBKDF1", "HMAC-MD5", "HMAC-SHA1", "MD5withRSA", "SHA1withRSA", "SHA_1", "SHA1_", "_SHA1", "_SHA_1", "MD5_", "_MD5"}

weak_tls_versions := {"SSLv2", "SSLv3", "TLSv1.0", "TLSv1.1", "1.0", "1.1", "TLS-1.0", "TLS-1-1", "TLS-1.0-2010", "TLS-1-1-2017"}

weak_ssl_policies := {"COMPATIBILITY", "LEGACY", "WEAK", "COMPATIBLE", "ELBSecurityPolicy-TLS-1-0", "ELBSecurityPolicy-TLS-1-1"}

encryption_attr_names := {"algorithm", "cipher", "encryption", "encrypt", "type", "hash_algorithm", "digest", "kdf", "key_derivation", "mac", "hmac", "signature_algorithm", "kms_key_spec", "key_spec", "tls_version", "min_version", "ssl_policy", "tls_policy", "policy", "sse_algorithm", "iterations", "iteration_count", "salt_length", "memory", "memory_cost", "parallelism", "key_size", "key_length", "key_bits", "rsa_key_size", "modulus_size", "elliptic_curve", "cipher_suites", "ciphers", "auth_method"}

storage_encryption_names := {"storage_encrypted", "encryption_at_rest", "rotation"}

check_string_weak_alg(value) {
    value.ir_type == "String"
    alg := weak_algorithms[_]
    contains(upper(value.value), alg)
}

check_string_weak_cipher(value) {
    value.ir_type == "String"
    up := upper(value.value)
    contains(up, "CBC")
    contains(up, "SHA")
    not contains(up, "SHA256")
    not contains(up, "SHA384")
}

check_string_weak_cipher(value) {
    value.ir_type == "String"
    up := upper(value.value)
    contains(up, "NULL")
}

check_string_weak_cipher(value) {
    value.ir_type == "String"
    up := upper(value.value)
    contains(up, "EXPORT")
}

check_string_weak_cipher(value) {
    value.ir_type == "String"
    up := upper(value.value)
    contains(up, "DES")
}

check_string_weak_cipher(value) {
    value.ir_type == "String"
    up := upper(value.value)
    contains(up, "RC4")
}

check_string_weak_tls(value) {
    value.ir_type == "String"
    ver := weak_tls_versions[_]
    contains(upper(value.value), ver)
}

check_string_weak_ssl_policy(value) {
    value.ir_type == "String"
    pol := weak_ssl_policies[_]
    contains(upper(value.value), pol)
}

check_int_weak_key_size(value) {
    value.ir_type == "Integer"
    value.value < 128
    value.value > 0
}

check_string_weak_key_size(value) {
    value.ir_type == "String"
    regex.match("^(64|56|40|1024|512|768)$", value.value)
}

check_disabled_encryption(value) {
    value.ir_type == "Boolean"
    value.value == false
}

encryption_related_name(name) {
    enc := encryption_attr_names[_]
    contains(lower(name), enc)
}

storage_encryption_related_name(name) {
    enc := storage_encryption_names[_]
    contains(lower(name), enc)
}

extract_string_from_value(val) = str {
    val.ir_type == "String"
    str = val.value
} else = str {
    val.ir_type == "Integer"
    str = sprintf("%d", [val.value])
} else = str {
    val.ir_type == "Boolean"
    str = sprintf("%v", [val.value])
} else = str {
    val.ir_type == "VariableReference"
    str = val.value
} else = str {
    val.ir_type == "Null"
    str = "null"
}

glitch_hash_has_encryption_key(hash_node) {
    hash_node.ir_type == "Hash"
    kv := hash_node.value[_]
    kv.key.ir_type == "String"
    encryption_related_name(kv.key.value)
}

glitch_hash_has_weak_alg_value(hash_node) {
    hash_node.ir_type == "Hash"
    kv := hash_node.value[_]
    check_string_weak_alg(kv.value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    walk(parent, [_, node])
    node.ir_type == "Attribute"

