    lower_name == "auth_method"
}

is_weak_cipher_value(str) {
    upper_str := upper(str)
    contains(upper_str, "CBC")
    contains(upper_str, "SHA")
    not contains(upper_str, "SHA256")
    not contains(upper_str, "SHA384")
}

is_weak_cipher_value(str) {
